namespace TradeReconciliation.Core.Configuration;

/// <summary>
/// Externally configurable reconciliation tolerances. Defaults reproduce the
/// legacy .NET Framework batch exactly and must not be changed without a
/// business rule change.
/// </summary>
public sealed class ReconciliationOptions
{
    /// <summary>Legacy defaults, used whenever the caller supplies nothing else.</summary>
    public static ReconciliationOptions Default { get; } = new();

    /// <summary>Inclusive absolute tolerance between trade and position quantity.</summary>
    public decimal PositionQuantityTolerance { get; init; } = 0.01m;

    /// <summary>Inclusive absolute tolerance between trade and settlement quantity.</summary>
    public decimal SettlementQuantityTolerance { get; init; } = 0.02m;

    /// <summary>Inclusive absolute tolerance between trade net amount and settlement cash.</summary>
    public decimal SettlementAmountTolerance { get; init; } = 5.00m;
}

namespace TradeReconciliation.Core.Configuration;

/// <summary>Fixed file-name contract shared with downstream Trade Operations tooling.</summary>
public static class BatchFileNames
{
    public const string Trades = "trades.csv";
    public const string Positions = "positions.csv";
    public const string Settlements = "settlements.csv";
    public const string Overrides = "overrides.csv";

    public const string MatchedTrades = "matched-trades.csv";
    public const string BreakQueue = "break-queue.csv";
    public const string EndOfDayReport = "end-of-day-report.txt";
    public const string RunLedger = "run-ledger.csv";

    /// <summary>The four declared output files, in adapter declaration order.</summary>
    public static IReadOnlyList<string> Outputs { get; } =
    [
        MatchedTrades,
        BreakQueue,
        EndOfDayReport,
        RunLedger
    ];
}

using System.Globalization;

namespace TradeReconciliation.Core.Configuration;

/// <summary>
/// Formatting rules that make every output file byte-deterministic across
/// operating systems. The legacy batch relied on <see cref="Environment.NewLine"/>;
/// pinning "\n" keeps identical reruns byte-identical on any host while matching
/// the checked-in golden-master fixtures.
/// </summary>
public static class OutputFormat
{
    /// <summary>Line separator used for every generated file.</summary>
    public const string LineSeparator = "\n";

    /// <summary>Invariant date format used in every generated file.</summary>
    public const string DateFormat = "yyyy-MM-dd";

    /// <summary>Invariant quantity format: up to four decimals, no trailing zeroes.</summary>
    public const string DecimalFormat = "0.####";

    public static string FormatDate(DateTime value) =>
        value.ToString(DateFormat, CultureInfo.InvariantCulture);

    public static string FormatDecimal(decimal value) =>
        value.ToString(DecimalFormat, CultureInfo.InvariantCulture);

    /// <summary>Joins <paramref name="lines"/> with a trailing separator after the final line.</summary>
    public static string JoinLines(IEnumerable<string> lines) =>
        string.Concat(lines.Select(line => line + LineSeparator));
}

namespace TradeReconciliation.Core.Matching;

/// <summary>
/// Canonical text normalization for identity comparisons: account, instrument,
/// currency, trade identifier, and override action are all compared on trimmed
/// uppercase values.
/// </summary>
public static class TextNormalization
{
    public static string Normalize(string? value) =>
        (value ?? string.Empty).Trim().ToUpperInvariant();

    /// <summary>Account and instrument pair key used to bucket counterpart candidates.</summary>
    public static string BuildPairKey(string? account, string? instrument) =>
        Normalize(account) + "|" + Normalize(instrument);
}

namespace TradeReconciliation.Core.Matching;

/// <summary>
/// Break reason codes written to <c>break-queue.csv</c> and aggregated in the
/// end-of-day report. These strings are part of the external output contract.
/// </summary>
public static class BreakReasons
{
    public const string DuplicateTradeId = "DuplicateTradeId";
    public const string TradeValueOutOfBounds = "TradeValueOutOfBounds";

    public const string MissingPosition = "MissingPosition";
    public const string PositionSettlementDateMismatch = "PositionSettlementDateMismatch";
    public const string PositionCurrencyMismatch = "PositionCurrencyMismatch";
    public const string PositionQuantitySignMismatch = "PositionQuantitySignMismatch";
    public const string PositionQuantityOutOfTolerance = "PositionQuantityOutOfTolerance";

    public const string MissingSettlement = "MissingSettlement";
    public const string SettlementDateMismatch = "SettlementDateMismatch";
    public const string SettlementCurrencyMismatch = "SettlementCurrencyMismatch";
    public const string SettlementQuantitySignMismatch = "SettlementQuantitySignMismatch";
    public const string SettlementQuantityOutOfTolerance = "SettlementQuantityOutOfTolerance";
    public const string SettlementAmountOutOfTolerance = "SettlementAmountOutOfTolerance";

    /// <summary>
    /// Reasons that describe a missing or structurally impossible counterpart. A
    /// manual override may never resolve a break carrying one of these.
    /// </summary>
    public static bool BlocksManualOverride(string reason) =>
        reason is MissingPosition or MissingSettlement or DuplicateTradeId or TradeValueOutOfBounds;
}

namespace TradeReconciliation.Core.Matching;

/// <summary>Statuses written to the <c>status</c> column of <c>matched-trades.csv</c>.</summary>
public static class MatchStatuses
{
    public const string Matched = "Matched";
    public const string ManualOverrideMatched = "ManualOverrideMatched";
    public const string ManualOverrideSuppressed = "ManualOverrideSuppressed";
}

/// <summary>Normalized manual override actions accepted by the matching engine.</summary>
public static class OverrideActions
{
    public const string ForceMatch = "FORCEMATCH";
    public const string SuppressBreak = "SUPPRESSBREAK";
}

